import{_ as r,o as n,c as t,a0 as e}from"./chunks/framework.D7EjqxMK.js";const c=JSON.parse('{"title":"LangGraph 有向图编排","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/02_核心框架/02_LangGraph有向图编排.md","filePath":"06-agent/02_核心框架/02_LangGraph有向图编排.md"}'),o={name:"06-agent/02_核心框架/02_LangGraph有向图编排.md"};function g(l,a,h,s,i,_){return n(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="langgraph-有向图编排" tabindex="-1">LangGraph 有向图编排 <a class="header-anchor" href="#langgraph-有向图编排" aria-label="Permalink to &quot;LangGraph 有向图编排&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块二 · 02_核心框架 · 第 2 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：LangChain 基础</p></blockquote><hr><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>LangGraph</strong> 是 LangChain 团队推出的有向图编排框架，用于构建<strong>有状态、可循环</strong>的 Agent 工作流。</p><p>核心差异：LangChain 的 Chain 是<strong>无状态链式</strong>（线性执行），LangGraph 是<strong>有状态图式</strong>（可循环、可分支）。<a href="https://edu.guangjuke.com/haowen/360.html" target="_blank" rel="noreferrer">来源: Guangjuke - AI Agent开发框架终极决策树</a></p><hr><h2 id="_2-核心概念" tabindex="-1">2. 核心概念 <a class="header-anchor" href="#_2-核心概念" aria-label="Permalink to &quot;2. 核心概念&quot;">​</a></h2><h3 id="三大核心概念" tabindex="-1">三大核心概念 <a class="header-anchor" href="#三大核心概念" aria-label="Permalink to &quot;三大核心概念&quot;">​</a></h3><p>| 概念 | 说明 | 类比 | |--|-|--|- | | <strong>Node</strong> | 图中的节点，执行具体逻辑 | 函数/步骤 | | <strong>Edge</strong> | 节点之间的连线，定义流向 | 路由/分支 | | <strong>State</strong> | 跨节点共享的状态数据 | 内存/上下文 |</p><h3 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h3><ul><li>Agent 需要<strong>循环决策</strong>（执行→评估→修正→再执行）</li><li>工作流有<strong>分支和合并</strong></li><li>需要<strong>持久化状态</strong>（跨步骤保存进度）</li><li>Agent 需要<strong>中断和恢复</strong></li></ul><hr><h2 id="_3-参考资料" tabindex="-1">3. 参考资料 <a class="header-anchor" href="#_3-参考资料" aria-label="Permalink to &quot;3. 参考资料&quot;">​</a></h2><ul><li><a href="https://langchain-ai.github.io/langgraph/" target="_blank" rel="noreferrer">LangGraph 官方文档</a></li><li><a href="https://blog.langchain.dev/langgraph/" target="_blank" rel="noreferrer">LangGraph 博客</a></li><li><a href="https://nicklaunches.com/blog/ai-agent-frameworks-comparison-2025/" target="_blank" rel="noreferrer">Comparing 5 AI Agent Frameworks</a></li></ul>',15)])])}const d=r(o,[["render",g]]);export{c as __pageData,d as default};
